"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/what-we-offer/variants/01-ai-operations";
import Variant1 from "./components/what-we-offer/variants/02-control-stack";
import Variant2 from "./components/what-we-offer/variants/03-connected-workflow";
const variants = {"ai-operations": Variant0,"control-stack": Variant1,"connected-workflow": Variant2};
export interface ArtemisWhatWeOfferProps { className?: string; variant?: "ai-operations" | "control-stack" | "connected-workflow"; }
export function ArtemisWhatWeOffer({ className, variant = "ai-operations" }: ArtemisWhatWeOfferProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }
